local function to_fullpath(path)
    local ext_file_dir = E.File.get_ext_file_dir()
    local fullpath_result = E.Path.join(ext_file_dir, path)
    return fullpath_result
end

--[[
重命名文件或者目录，
以下场景会rename失败：
1. 如果目标目录存在且不为空

@param src: string, 必传，源文件相对路径，相对路径见E.File.get_ext_file_dir()
@param dst：string, 必传，目标文件相对路径
@param opts: table, 可选，可选项, 包含以下内容：
    @param is_fullpath: bool, 默认为false, true：当前src和dst为绝对路径

@return bool true rename成功； nil rename 失败，同时第二个参数为msg
--]]
M.rename = function(src, dst, opts)
    local src_full_path
    local dst_full_path

    opts = opts or {}
    local is_fullpath = opts.is_fullpath
    if not is_fullpath then
        src_full_path = to_fullpath(src)
        dst_full_path = to_fullpath(dst)
    else
        src_full_path = src
        dst_full_path = dst
    end

    return M.rename_fullpath(src_full_path, dst_full_path)
end

