@param opts: table, 可选，可选项, 包含以下内容：
    @param is_fullpath: bool, 默认为false, true：当前src和dst为绝对路径
--]]
M.batch_rename = function(map, cb, opts)
    map = map or {}
    if next(map) == nil then
        cb(true)
        return
    end

    opts = opts or {}
    local fullpath_map
    local is_fullpath = opts.is_fullpath
    if not is_fullpath then
        fullpath_map = {}
