--[[
批量删除文件或者目录
@param file_list: table, 文件或目录字符串列表
@param cb: function, 结果回调，返回内容如下：
    @param succ: bool, true：全部删除成功；false: 部分失败或全部失败，此时code, msg, result_ext不为空
    @param code: number, 错误码
    @param msg: string, 错误信息
    @param result_ext: table, 失败的路径信息，包含以下key-value值
        key string，源文件路径
        value table, 错误信息，包含以下key-value
            @param code number 错误码
            @param msg string 错误信息
@param opts: table, 可选，可选项, 包含以下内容：
    @param is_fullpath: bool, 默认为false, true：当前src和dst为绝对路径
--]]
M.batch_remove = function(file_list, cb, opts)
    file_list = file_list or {}
    local size = #file_list
    if size == 0 then
        cb(true)
        return
    end

    opts = opts or {}
    local fullpath_list
    local is_fullpath = opts.is_fullpath
    if not is_fullpath then
        fullpath_list = {}
        for _, path in ipairs(file_list) do
            local full_path = to_fullpath(path)
            table.insert(fullpath_list, full_path)
        end
    else
        fullpath_list = file_list
    end

    E.File.process_batch_remove(fullpath_list, cb, opts)
end

