--[[
批量返回文件的md5值
@param file_list：table, 为文件路径数组，相对路径见E.File.get_ext_file_dir()
@param cb: function, 结果回调，包含以下返回值
    @param succ, bool, true：成功，则第二个参数为succ_data; false: 单个或全部失败，此时后面参数分别为code, msg, succ_data, fail_data
    @param code number，错误码
    @param msg string, 错误信息
    @param succ_data table, 多个文件md5值，k-v格式，对应内容如下：
            key: 文件路径
            value: md5值
    @param fail_data table, 多个路径对应的错误信息
@param is_full_path: bool, 是否是完整路径，默认为false
--]]
M.batch_md5 = function(file_list, cb, is_full_path)
    file_list = file_list or {}
    local size = #file_list
    if size == 0 then
        cb(true, {})
        return
    end

    local fullpath_list
    local full_rela_path_map
    if not is_full_path then
        fullpath_list = {}
        full_rela_path_map = {}
        for _, path in ipairs(file_list) do
            local full_path = to_fullpath(path)
            table.insert(fullpath_list, full_path)
            full_rela_path_map[full_path] = path
        end
    else
        fullpath_list = file_list
    end

    E.File.process_batch_md5(fullpath_list, function(succ, ...)
        if succ then
            local succ_data = ...
            succ_data = succ_data or {}
            local result_data = succ_data
            if full_rela_path_map then
                result_data = {}
                for abs_path, md5 in pairs(succ_data) do
                    local rela_path = full_rela_path_map[abs_path]
                    result_data[rela_path] = md5
                end
            end

            if cb then
                cb(true, result_data)
            end
        else
            local code, msg, succ_data, fail_data = ...
            local result_succ_data = succ_data
            local result_fail_data = fail_data
            if full_rela_path_map then
                result_succ_data = {}
                result_fail_data = {}

                for p1, md5 in pairs(succ_data) do
                    local rela_path = full_rela_path_map[p1]
                    result_succ_data[rela_path] = md5
                end

                for p2, md5 in pairs(fail_data) do
                    local rela_path = full_rela_path_map[p2]
                    result_fail_data[rela_path] = md5
                end
            end

            if cb then
                cb(false, code, msg, result_succ_data, result_fail_data)
            end
        end
    end)
end

--[[
批量检查文件状态
@param file_list：table, 为文件路径数组，相对路径见E.File.get_ext_file_dir()
@param cb: function, 结果回调，包含以下返回值
    @param succ_data table, 多个文件的状态信息，k-v格式，对应内容如下：
            key: 文件路径
            value: table, 包含的信息和opts配置相关，包含以下内容：
                @param exists: bool, 是否存在，true: 存在，false: 不存在
                @param size: number, 文件大小
@param opts: table, 可选项信息，包含以下信息
    @param is_full_path: bool，是否完整路径，默认为false, 相对路径见E.File.get_ext_file_dir()。true: 为绝对路径
    @param check_size: bool, 是否返回size， 默认为false, 不返回，如果设置为true会返回size
    @param base_path: string, 根路径，根路径+file_list里面的item=完整路径
--]]
M.batch_info = function(file_list, cb, opts)
    file_list = file_list or {}
    local size = #file_list
    if size == 0 then
        cb(true, {})
        return
    end

    opts = opts or {}
    local fullpath_list = file_list
    local is_full_path = opts.is_full_path
    if not is_full_path and (not opts.base_path or opts.base_path == '') then
        opts.base_path = E.Path.get_ext_file_dir()
    end

    E.File.process_batch_info(fullpath_list, function(succ_data)
        succ_data = succ_data or {}
        local result_data = succ_data

        if cb then
            cb(result_data)
        end
    end, opts)
end

