    @param ret: table, 为文件数组信息，每一项的类型为table, 包含字段如下：
        @param is_dir: bool, true: 是目录，false: 非目录
        @param path: string, 文件路径，相对于当前的dir_path
--]]
M.list_directory = function(dir_path, recursive, is_full_path, cb)
    if not dir_path or dir_path == '' then
        return nil, CC.EJOY_LIB_ERROR.PARAMETER_INVALID, "path is nil"
    end

    local abs_path
    if not is_full_path then
